s = input()
k = int(input()) % 26
r = []
for c in s:
    if 'a' <= c <= 'z':
        r.append(chr((ord(c) - 97 + k) % 26 + 97))
    elif 'A' <= c <= 'Z':
        r.append(chr((ord(c) - 65 + k) % 26 + 65))
    else:
        r.append(c)
print(''.join(r))

s = input()
v = c = 0
for ch in s:
    if ch.isalpha() and ch.isascii():
        if ch.lower() in 'aeiou':
            v += 1
        else:
            c += 1
print("Vowels:", v)
print("Consonants:", c)

s = input().lower()
cnt = {}
for c in s:
    if 'a' <= c <= 'z':
        cnt[c] = cnt.get(c, 0) + 1
best = min(cnt, key=lambda c: (-cnt[c], c))
print(best, cnt[best])

n = int(input())
if n == 0:
    print(0)
else:
    d = []
    while n:
        d.append(str(n & 1))
        n >>= 1
    print(''.join(reversed(d)))
